set-variable.value:
@{
      try
      {
        var body = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
        if (body == null) { return false; }
        var model = (string)body["model"];
        var modelAllowed =
          model == "gpt-5.4-nano" ||
          model == "gpt-5.4-mini" ||
          model == "gpt-5.6-sol" ||
          model == "deepseek-v4-pro" ||
          model == "grok-4.1-fast-reasoning" ||
          model == "llama-4-maverick" ||
          model == "kimi-k2.6" ||
          model == "mistral-large-3" ||
          model == "phi-4-mini" ||
          model == "gpt-4.1-nano" ||
          model == "gpt-4.1-mini";
        var maxTokens = (int?)body["max_completion_tokens"] ?? (int?)body["max_tokens"];
        return modelAllowed && maxTokens.HasValue && maxTokens.Value > 0 &&
          maxTokens.Value <= 4000 && body["messages"] != null;
      }
      catch
      {
        return false;
      }
    }
